# frozen_string_literal: true
# typed: true

require "test_helper"

class GemspecTest < Minitest::Test
  ROOT = File.expand_path("..", __dir__)
  CONFIG_RB = File.join(ROOT, "lib/llvm/config.rb")

  # lib/llvm/config.rb is generated by ext/ruby-llvm-support/Rakefile at install
  # time. A packaged copy stops that from happening and ships the values from
  # whichever LLVM the gem was built against.
  def test_generated_config_is_not_packaged
    assert_path_exists CONFIG_RB, "precondition: run rake in ext/ruby-llvm-support to generate config.rb"
    refute_includes spec_files, "lib/llvm/config.rb"
  end

  def test_library_files_are_packaged
    assert_includes spec_files, "lib/llvm/version.rb"
  end

  private

  def spec_files
    Dir.chdir(ROOT) do
      spec = Gem::Specification.load(File.join(ROOT, "ruby-llvm.gemspec")) #: as !nil
      spec.files
    end
  end
end
